257	func TestResumeRunningExecutionSkipsConfirmedStep(t *testing.T) {
258		store := NewMemoryStore()
259		eng := NewEngine(store)
260		rec := &recorder{}
261		def := threeStepDef(rec, "", "")
262	
263		// 模拟崩溃恢复：reserve 已确认成功（状态已提交），charge/ship 尚未执行。
