464		}); err != nil {
465			t.Fatal(err)
466		}
467	
468		// 第一轮：事件被领取，但尚未 Ack/Nack 时不会重复领取。
469		batch1, err := store.ClaimPendingEvents(context.Background(), 100)
470		if err != nil {
471			t.Fatal(err)
472		}
473		if len(batch1) == 0 {
474			t.Fatal("expected events")
475		}
476		again, _ := store.ClaimPendingEvents(context.Background(), 100)
477		if len(again) != 0 {
478			t.Fatalf("claimed events must be hidden from re-claim, got %d", len(again))
479		}
480	
481		// 发送失败：退回全部原事件，负载不变，之后可再次领取且投递次数增加。
482		ev := batch1[0]
483		originalType := ev.Type
484		for _, e := range batch1 {
485			if err := store.NackEvent(context.Background(), e.ID); err != nil {
486				t.Fatal(err)
487			}
488		}
489		batch2, _ := store.ClaimPendingEvents(context.Background(), 100)
490		if len(batch2) != len(batch1) {
491			t.Fatalf("after nack all events reclaimable: got %d want %d", len(batch2), len(batch1))
492		}
493		var retried *Event
494		for _, e := range batch2 {
495			if e.ID == ev.ID {
496				retried = e
497			}
498		}
499		if retried == nil {
500			t.Fatal("nacked event missing from reclaim")
501		}
502		if retried.Type != originalType {
503			t.Fatalf("event payload/type altered: %s -> %s", originalType, retried.Type)
504		}
