// flakyAction 前 failTimes 次返回固定错误，之后成功，并记录总调用次数。
func flakyAction(rec *recorder, name string, failTimes int) ActionFunc {
	n := 0
	return func(_ context.Context, _ ExecutionView) error {
		rec.call("do:" + name)
		n++
		if n <= failTimes {
			return errors.New("transient-" + name)
		}
		return nil
	}
}

func flakyCompensate(rec *recorder, name string, failTimes int) CompensationFunc {
	n := 0
	return func(_ context.Context, _ ExecutionView) error {
		rec.call("undo:" + name)
		n++
		if n <= failTimes {
			return errors.New("comp-transient-" + name)
		}
		return nil
	}
}

